import socket
import time
from select import select
from .response_queue import RCIResponseQueue


class RCISocket(object):
    """ Wraps around low level python socket API and RCI protocol details. """
    RECV_BUFSIZE = 4096

    def __init__(self, ip, port):
        self._ip = ip
        self._port = port
        self._socket = None
        self.buffer = RCIResponseQueue()

    def connect(self, timeout=None):
        self._socket = socket.create_connection((self._ip, self._port), timeout)

    def disconnect(self):
        self._socket.shutdown(socket.SHUT_RDWR)
        self._socket.close()

    def send_message(self, message):
        """ Send a message to the remote.

        The data sent will always end with CRLF ('\r\n'), even if the message
        itself doesn't end with one.
        """
        if not message.endswith('\r\n'):
            message += '\r\n'
        data = message.encode()

        self._socket.sendall(data)

    def recv_messages(self, timeout=None):
        """ Receive at least one full message from the remote host.

        Returns a list of fully received messages. If no message is available,
        this routine will block until it either receives one or reaches a
        timeout, in which case socket.timeout is raised.

        If timeout is 0, this routine becomes non-blocking. It will try to read
        from the remote, and return as many messages as are available. The
        number of available messages at once depends on RECV_BUFSIZE
        classfield. At most RECV_BUFSIZE data can be read at any given time,
        and only complete messages will be returned.

        If no complete message is available, an empty list will be returned.
        """

        if timeout == 0 or self.buffer.message_ready:
            self._recv_nonblocking()
        else:
            self._recv_blocking(timeout)

        return self.buffer.get_available()

    def _recv_nonblocking(self):
        if not self._recv_ready():
            return
        new_data = self._recv()
        self.buffer.put(new_data)

    def _recv_blocking(self, timeout):
        """ Receive, wait until a message is ready or raise timeout.

        Tries to receive all messages that are available.
        """
        # XXX: This always does a socket.recv() at least once, even if a full
        # message is already buffered and ready to be returned.
        # TODO: This should use time.monotonic(). Replace it whenever python2
        # compat is dropped.
        start = time.time()

        while True:
            if timeout is not None:
                self._check_remaining_time(timeout, start)

            if self._recv_ready(timeout):
                new_data = self._recv_all()
                self.buffer.put(new_data)

            if self.buffer.message_ready:
                return

    @staticmethod
    def _check_remaining_time(timeout, start_time):
        # TODO: replace with time.monotonic() after python2 compat is dropped
        remaining = timeout - (time.time() - start_time)
        if remaining <= 0:
            raise socket.timeout("timed out while receiving a message")

    def _recv_ready(self, timeout=0):
        ready, _, _ = select([self._socket], [], [], timeout)
        return self._socket in ready

    def _recv_all(self):
        data = ''
        while self._recv_ready():
            data += self._recv()
        return data

    def _recv(self):
        return self._socket.recv(self.RECV_BUFSIZE).decode()
